const choice = document.querySelector('#email-choice');
const frame = document.querySelector('#frame');
let frameObserver;
frame.addEventListener('load', () => {
 if (frameObserver) frameObserver.disconnect();
 const resize = () => {frame.style.height = Math.ceil(frame.contentDocument.body.getBoundingClientRect().height + 2) + 'px';};
 frameObserver = new ResizeObserver(resize);
 frameObserver.observe(frame.contentDocument.body);
 frame.contentDocument.fonts.ready.then(resize);
 resize();
 frame.contentWindow.scrollTo(0,0);
});
const assets = {welcome_art_url:'assets/welcome.png',promotion_art_url:'assets/promotion.png',seasonal_art_url:'assets/seasonal.png',basket_art_url:'assets/basket.png',order_art_url:'assets/order.png',delivery_art_url:'assets/delivery.png',refund_art_url:'assets/refund.png',hero_image_url:'../storefront/hero-produce.jpg',farm_image_url:'../storefront/hero-swedish-farmhouse.jpg',logo_url:'../storefront/farmtotable-logo-dark.png',heading_font_url:'fonts/cormorant-latin.woff2',body_font_url:'fonts/montserrat-latin.woff2',verify_art_url:'assets/verify.png',reset_art_url:'assets/reset.png',secure_art_url:'assets/secure.png'};
const samples = { first_name:'Alex', expiry_duration:'30 minutes', changed_at:'21 September 2026, 10:30 CEST', offer_title:'A seasonal treat', offer_description:'10% off', eligible_products:'selected seasonal vegetables', promo_code:'FRESH10', offer_end_date:'30 September 2026', offer_timezone:'CEST', offer_terms:'Illustrative offer only. Minimum basket 300 SEK. Maximum discount 100 SEK. One use per customer. Cannot be combined with other offers.', seasonal_highlight:'autumn harvest vegetables', farm_story:'Meet the growers bringing this week’s seasonal picks to the market', recipe_teaser:'Roast root vegetables with herbs for a simple, colourful supper', cart_summary:'Your basket: carrots, potatoes and local honey', order_number:'FTT-1042', order_items_summary:'Carrots × 1 · Potatoes × 1 · Honey × 1', subtotal:'320 SEK', delivery_fee:'49 SEK', discount:'0 SEK', order_total:'369 SEK', delivery_address:'Sample delivery address, Stockholm', delivery_window:'23 September, 16:00–18:00', seller_name:'Example Farm', delivery_status:'Your order has been dispatched', delivery_instructions:'Please be available at your delivery address', refund_status:'Approved', refund_amount:'80 SEK', refund_method:'Original payment method', refund_reason:'An item was unavailable', refund_timeline:'5–10 business days (illustrative)', business_name:'Farm to Table · Sample company', business_address:'Business address to be confirmed', year:'2026' };
function render() {
 const t = templates[choice.value];
 document.querySelector('#title').textContent = t.title;
 document.querySelector('#subject').textContent = 'Subject: ' + t.subject.replace(/{{(\w+)}}/g, (_,key) => samples[key] || '['+key+']');
 const sourceName = choice.value === 'welcome' ? 'welcome-template' : choice.value;
 const src = 'emails/' + sourceName;
 document.querySelector('#download').href = 'standalone/' + choice.value + '.html';
 document.querySelector('#plain').href = 'emails/' + choice.value + '.txt';
 document.querySelector('#raw').href = src + '.html';
 let html = t.html.replace(/{{(\w+)}}/g, (_,key) => Object.hasOwn(assets,key) ? assets[key] : key.endsWith('_url') ? '#' : samples[key] || '['+key+']');
 html = html.replace(/<a href="[^"]*"/g, '<a aria-disabled="true"').replace('</head>', '<style>a{pointer-events:none}</style></head>');
 frame.srcdoc = html;
 history.replaceState(null, '', '?email=' + choice.value);
}
const initial = new URLSearchParams(location.search).get('email');
if (Object.hasOwn(templates, initial)) choice.value = initial;
choice.addEventListener('change', render);
document.querySelector('#mobile').onclick = () => {frame.style.maxWidth='375px';document.querySelector('#mobile').setAttribute('aria-pressed','true');document.querySelector('#desktop').setAttribute('aria-pressed','false');};
document.querySelector('#desktop').onclick = () => {frame.style.maxWidth='100%';document.querySelector('#desktop').setAttribute('aria-pressed','true');document.querySelector('#mobile').setAttribute('aria-pressed','false');};
render();
